-- charstartoutfit: copied from the closest stock race at build time (after F-002's ARAC outfits)

-- @Banshee: the outfits of @BansheeHome; classes it lacks come from @Orc, @Troll, @Tauren, @BloodElf
DELETE FROM `charstartoutfit` WHERE `race` = @Banshee;
SET @CharStartOutfitID = (SELECT COALESCE(MAX(id), 0) FROM `charstartoutfit`);
INSERT INTO `charstartoutfit` (`id`, `race`, `class`, `gender`, `outfit_id`, `item_1`, `item_2`, `item_3`, `item_4`, `item_5`, `item_6`, `item_7`, `item_8`, `item_9`, `item_10`, `item_11`, `item_12`, `item_13`, `item_14`, `item_15`, `item_16`, `item_17`, `item_18`, `item_19`, `item_20`, `item_21`, `item_22`, `item_23`, `item_24`, `display_item_1`, `display_item_2`, `display_item_3`, `display_item_4`, `display_item_5`, `display_item_6`, `display_item_7`, `display_item_8`, `display_item_9`, `display_item_10`, `display_item_11`, `display_item_12`, `display_item_13`, `display_item_14`, `display_item_15`, `display_item_16`, `display_item_17`, `display_item_18`, `display_item_19`, `display_item_20`, `display_item_21`, `display_item_22`, `display_item_23`, `display_item_24`, `inventory_type_1`, `inventory_type_2`, `inventory_type_3`, `inventory_type_4`, `inventory_type_5`, `inventory_type_6`, `inventory_type_7`, `inventory_type_8`, `inventory_type_9`, `inventory_type_10`, `inventory_type_11`, `inventory_type_12`, `inventory_type_13`, `inventory_type_14`, `inventory_type_15`, `inventory_type_16`, `inventory_type_17`, `inventory_type_18`, `inventory_type_19`, `inventory_type_20`, `inventory_type_21`, `inventory_type_22`, `inventory_type_23`, `inventory_type_24`)
SELECT @CharStartOutfitID := @CharStartOutfitID +1, @Banshee, `o`.`class`, `o`.`gender`, `o`.`outfit_id`, `o`.`item_1`, `o`.`item_2`, `o`.`item_3`, `o`.`item_4`, `o`.`item_5`, `o`.`item_6`, `o`.`item_7`, `o`.`item_8`, `o`.`item_9`, `o`.`item_10`, `o`.`item_11`, `o`.`item_12`, `o`.`item_13`, `o`.`item_14`, `o`.`item_15`, `o`.`item_16`, `o`.`item_17`, `o`.`item_18`, `o`.`item_19`, `o`.`item_20`, `o`.`item_21`, `o`.`item_22`, `o`.`item_23`, `o`.`item_24`, `o`.`display_item_1`, `o`.`display_item_2`, `o`.`display_item_3`, `o`.`display_item_4`, `o`.`display_item_5`, `o`.`display_item_6`, `o`.`display_item_7`, `o`.`display_item_8`, `o`.`display_item_9`, `o`.`display_item_10`, `o`.`display_item_11`, `o`.`display_item_12`, `o`.`display_item_13`, `o`.`display_item_14`, `o`.`display_item_15`, `o`.`display_item_16`, `o`.`display_item_17`, `o`.`display_item_18`, `o`.`display_item_19`, `o`.`display_item_20`, `o`.`display_item_21`, `o`.`display_item_22`, `o`.`display_item_23`, `o`.`display_item_24`, `o`.`inventory_type_1`, `o`.`inventory_type_2`, `o`.`inventory_type_3`, `o`.`inventory_type_4`, `o`.`inventory_type_5`, `o`.`inventory_type_6`, `o`.`inventory_type_7`, `o`.`inventory_type_8`, `o`.`inventory_type_9`, `o`.`inventory_type_10`, `o`.`inventory_type_11`, `o`.`inventory_type_12`, `o`.`inventory_type_13`, `o`.`inventory_type_14`, `o`.`inventory_type_15`, `o`.`inventory_type_16`, `o`.`inventory_type_17`, `o`.`inventory_type_18`, `o`.`inventory_type_19`, `o`.`inventory_type_20`, `o`.`inventory_type_21`, `o`.`inventory_type_22`, `o`.`inventory_type_23`, `o`.`inventory_type_24`
FROM (SELECT * FROM `charstartoutfit` WHERE FIELD(`race`, @Undead, @Orc, @Troll, @Tauren, @BloodElf) > 0) AS `o`
JOIN (SELECT `class`, `gender`, MIN(FIELD(`race`, @Undead, @Orc, @Troll, @Tauren, @BloodElf)) AS `pick` FROM `charstartoutfit`
      WHERE FIELD(`race`, @Undead, @Orc, @Troll, @Tauren, @BloodElf) > 0 GROUP BY `class`, `gender`) AS `best`
  ON `best`.`class` = `o`.`class` AND `best`.`gender` = `o`.`gender` AND FIELD(`o`.`race`, @Undead, @Orc, @Troll, @Tauren, @BloodElf) = `best`.`pick`
ORDER BY `o`.`class`, `o`.`gender`;
